import{_ as t,a,b as o,c as s,d as r,e as i,f as n,g as l,h,i as c,j as p,k as m,l as d,m as u,n as g,o as y,p as _,q as f,r as w,s as b,t as x,u as z,v as D,w as v,x as k,y as P,z as S,A as q,B as I,C as T,D as W,E as A,F as G,G as B,H as C,I as N,J as E,K as F,L as O,M as L,N as V,O as $,P as K,Q as X,R as Y,S as R,T as J}from"./chunks/M-S-SW-AW-ST13.BF6FVufy.js";import{_ as U}from"./chunks/M-S-SW-AW-3DM.DGzdotDO.js";import{_ as j,o as H,c as M,a3 as Q}from"./chunks/framework.g9mfNVRQ.js";const he=JSON.parse('{"title":"Use Wear Extension","description":"","frontmatter":{},"headers":[],"relativePath":"smartwatch/usewear.md","filePath":"smartwatch/usewear.md"}'),Z={name:"smartwatch/usewear.md"};function ee(te,e,ae,oe,se,re){return H(),M("div",null,[...e[0]||(e[0]=[Q('<p>You will find the reference documentation <a href="https://github.com/NightscoutFoundation/xDrip/blob/master/Documentation/WatchGuide.md" target="_blank" rel="noreferrer">here</a>.</p><h2 id="discover-wear-extension" tabindex="-1">Discover Wear Extension <a class="header-anchor" href="#discover-wear-extension" aria-label="Permalink to &quot;Discover Wear Extension&quot;">​</a></h2><p>Four native watchfaces are available from xDrip.</p><table tabindex="0"><thead><tr><th style="text-align:center;">XDrip</th><th style="text-align:center;">XDrip(BigChart)</th></tr></thead><tbody><tr><td style="text-align:center;"><img src="'+t+'" style="zoom:75%;"></td><td style="text-align:center;"><img src="'+a+'" style="zoom:75%;"></td></tr><tr><td style="text-align:center;"><strong>XDrip(Large)</strong></td><td style="text-align:center;"><strong>XDrip(Circle)</strong></td></tr><tr><td style="text-align:center;"><img src="'+o+'" style="zoom:75%;"></td><td style="text-align:center;"><img src="'+s+'" style="zoom:75%;"></td></tr></tbody></table><p>Graph based watchfaces contain some common elements with the xDrip main display.</p><ol><li>What&#39;s the last measured BG value.<br> What&#39;s the BG difference with the previous value received.<br> What&#39;s the trend with respect to the previous measurement.</li><li>A status line.</li><li>A BG graph.</li></ol><img src="'+r+'" style="zoom:75%;"><p>Double tapping the graph changes the time scale.</p><img src="'+i+'" style="zoom:75%;"><p>Since xDrip wear extension contains some of the app code, you will find xDrip menu items on the watch. You will find them inside the watch apps, some can also be accessed from the watch graph using the three dots menu present on all watchfaces.</p><img src="'+U+'" style="zoom:75%;"><h3 id="xdrip-prefs" tabindex="-1">xDrip Prefs. <a class="header-anchor" href="#xdrip-prefs" aria-label="Permalink to &quot;xDrip Prefs.&quot;">​</a></h3><p>This menu contains display options for your watchface.<br> When the watch is set up in standalone collector, more items will be visible. See below.</p><img src="'+n+'" style="zoom:75%;"><p>Dark theme shows a black background and white text/graph. Disabling it shows the opposite: a white background and dark text/graph.</p><img src="'+l+'" style="zoom:75%;"><p>Refresh on change updates the watchface every data change (5 minutes minimum). If you disable it the watch will update its watchface every minute (will use more battery).</p><img src="'+h+'" style="zoom:75%;"><p>Show treatment adds treatment dots on the graph watchfaces.</p><img src="'+c+'" style="zoom:75%;"><p>24 hours format forces this time format to display.</p><img src="'+p+'" style="zoom:75%;"><p>Show date also shows the date on the watchface.</p><img src="'+m+'" style="zoom:75%;"><p>If your watch is set up to use its own locale (language) you can force it to use the phone settings.</p><img src="'+d+'" style="zoom:75%;"><p>Toasts are pop-up messages, you can enable them and have extra information by tapping steps and status on the watch.</p><img src="'+u+'" style="zoom:75%;"><p>If your watch supports it and you authorized xDrip Prefs. to access sensor data on the watch you will have the step counter on the watchface and can have <a href="./../use/display.html">steps data</a> displayed on your phone xDrip.</p><img src="'+g+'" style="zoom:75%;"><p>If your watch supports it and you authorized xDrip Prefs. to access sensor data on the watch you will have heart rate on the watchface and can have <a href="./../use/display.html">heart rate data</a> displayed on your phone xDrip.</p><img src="'+y+'" style="zoom:75%;"><p>If you use an open source closed loop system (like AAPS) broadcasting data to xDrip, you can have loop status added to the status line.</p><img src="'+_+'" style="zoom:75%;"><p>By default the watchface will display the collecting device battery as <code>uploader</code> or <code>wear</code>. This is a legacy definition that doesn&#39;t add value if you&#39;re not using xDrip as master: it will not display the master phone battery level nor a possible bridge device battery but only your phone and watch battery.</p><img src="'+f+'" style="zoom:75%;"><p>Allows you to display cards (alerts) with a plain background to improve readability.</p><img src="'+w+'" style="zoom:75%;"><p>You can change the font size of the status line. 10 or 12 points.</p><img src="'+b+'" style="zoom:75%;"><p>You can change the chart timeframe, same as double tapping it.</p><img src="'+x+'" style="zoom:75%;"><p>In this menu you&#39;ll find customizations for the circle watchface.</p><img src="'+z+'" style="zoom:75%;"><p>Low color.</p><img src="'+D+'" style="zoom:75%;"><p>On xDrip and xDrip Large, change the divider (status line) color to match background.</p><img src="'+v+'" style="zoom:75%;"><p>Force update is available for Wear 2.0 and above watches if available for the current version and enabled as explained <a href="./wearinstall.html#wear-os-2x-and-3x">here</a>.</p><img src="'+k+'" style="zoom:75%;"><p>Demigod is available for <a href="https://github.com/NightscoutFoundation/xDrip/wiki/Patching-Android-Wear-devices-for-use-with-the-G5" target="_blank" rel="noreferrer">patched watches</a>.</p><img src="'+P+'" style="zoom:75%;"><h3 id="keypad-treatment" tabindex="-1">Keypad Treatment <a class="header-anchor" href="#keypad-treatment" aria-label="Permalink to &quot;Keypad Treatment&quot;">​</a></h3><p>Keypad treatment is identical to xDrip <a href="./../use/mainUI.html#treatments">syringe icon</a>.</p><img src="'+S+'" style="zoom:75%;"><img src="'+q+'" style="zoom:75%;"><h3 id="spoken-treatment" tabindex="-1">Spoken treatment <a class="header-anchor" href="#spoken-treatment" aria-label="Permalink to &quot;Spoken treatment&quot;">​</a></h3><p>Spoken treatment is identical to xDrip.</p><img src="'+I+'" style="zoom:75%;"><img src="'+T+'" style="zoom:75%;"><h3 id="snooze-alert" tabindex="-1">Snooze Alert <a class="header-anchor" href="#snooze-alert" aria-label="Permalink to &quot;Snooze Alert&quot;">​</a></h3><p>Not all alerts and alarms are available on the watch.</p><img src="'+W+'" style="zoom:75%;"><p>On wear 1.x alarms and alerts that lead to opening on the phone means you need to perform snooze from within the phone xDrip app.</p><img src="'+A+'" style="zoom:75%;"><p>On wear 2.x and above alerts might show as notifications and you will need to manually open the snooze alert phone app or snooze them from the phone xDrip app.</p><img src="'+G+'" style="zoom:75%;"><h2 id="standalone-collector-mode" tabindex="-1"><a href="./wear.html#standalone-collector-mode">Standalone collector mode</a> <a class="header-anchor" href="#standalone-collector-mode" aria-label="Permalink to &quot;[Standalone collector mode](./wear#standalone-collector-mode)&quot;">​</a></h2><p>xDrip Prefs. menu will contain additional information mirrored from xDrip on the phone when both are connected together.</p><h4 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h4><p>A validation mechanism will make sure both use the same settings. If the watch doesn&#39;t accept the settings change from xDrip, they will be modified automatically to match the watch settings when both are connected.</p><ol><li>Settings are modified on the phone</li><li>Changes are sent to the watch, when connected</li><li>Watch tries to implement settings modifications</li><li>Watch settings are sent back to the phone (modified or not)</li><li>Phone settings are updated to reflect the watch settings, when connected</li></ol><img src="'+B+'" style="zoom:75%;"><p>This also works the other way round. If the watch settings are modified, they will be sent to the phone when connected. xDrip on the phone will validate the changes and send them back to the watch as a confirmation.</p><ol><li>Settings are modified on the watch</li><li>Changes are sent to the phone, when connected</li><li>xDrip on the phone validates settings modifications</li><li>Phone settings are sent back to the watch (validated or not)</li><li>Watch settings are updated to reflect the phone settings, when connected</li></ol><img src="'+C+'" style="zoom:75%;"><h4 id="xdrip-prefs-1" tabindex="-1">xDrip Prefs. <a class="header-anchor" href="#xdrip-prefs-1" aria-label="Permalink to &quot;xDrip Prefs.&quot;">​</a></h4><p>When standalone collector is enabled you&#39;ll find additional entries in the menu.</p><p>BT collector shows which hardware data source collector is set on your phone xDrip.</p><img src="'+N+'" style="zoom:75%;"><p>Enable collector matches the setting in <a href="./wear.html#standalone-collector-mode">Wear integration</a>.</p><img src="'+E+'" style="zoom:75%;"><p>So does force collector. If the watch is not connected to the phone and you lost connection to your sensor you can try to trigger this to force a reconnection attempt.</p><img src="'+F+'" style="zoom:75%;"><p>When in standalone collector mode you can use the watch local alerts (some). They will be snoozed on the watch.</p><img src="'+O+'" style="zoom:75%;"><p>Including persistent high alert.</p><img src="'+L+'" style="zoom:75%;"><p>If your watch has a speaker it can also ring the alarms.</p><img src="'+V+'" style="zoom:75%;"><p>If you&#39;re connecting to a G5 or G6 you&#39;ll find additional settings.</p><img src="'+$+'" style="zoom:75%;"><p>These are replications of the phone Dex Debug Settings - Old G5 Collector Settings.</p><img src="'+K+'" style="zoom:75%;"><img src="'+X+'" style="zoom:75%;"><img src="'+Y+'" style="zoom:75%;"><img src="'+R+'" style="zoom:75%;"><p>Force screen on makes sure the watch will be fully awake when scanning.</p><img src="'+J+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',101)])])}const ce=j(Z,[["render",ee]]);export{he as __pageData,ce as default};
